1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { entryForPath, hrefMatches, type SubTabItem } from "@/lib/admin-groups";
6	
7	/**
8	 * Horizontal pill/tab bar for one admin entry's members. Highlights the active
9	 * item via usePathname (detail routes light up their tab too). Renders nothing
10	 * for a single-member entry — there is nothing to switch between.
11	 */
12	export function SubTabs({
13	  items,
14	  badges,
15	}: {
16	  items: SubTabItem[];
17	  /** Per-route attention counts, keyed by href. Shown as a pill on the tab. */
18	  badges?: Record<string, number>;
19	}) {
20	  const pathname = usePathname();
21	  if (items.length < 2) return null;
22	
23	  return (
24	    <nav className="mb-6 flex flex-wrap items-center gap-1.5 border-b border-white/[0.06] pb-3">
25	      {items.map((item) => {
26	        const active = hrefMatches(item.href, pathname);
27	        const count = badges?.[item.href] ?? 0;
28	        return (
29	          <Link
30	            key={item.href}
31	            href={item.href}
32	            className={`flex items-center gap-2 rounded-full px-3.5 py-1.5 text-[13px] font-medium transition-colors ${
33	              active
34	                ? "bg-brand-500/15 text-brand-200 ring-1 ring-inset ring-brand-500/40"
35	                : "text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
36	            }`}
37	          >
38	            {item.label}
39	            {count > 0 && (
40	              <span
41	                className={`flex h-[18px] min-w-[18px] items-center justify-center rounded-full px-1.5 text-[10px] font-semibold text-white ${
42	                  active ? "bg-brand-500" : "bg-brand-500/80"
43	                }`}
44	              >
45	                {count > 99 ? "99+" : count}
46	              </span>
47	            )}
48	          </Link>
49	        );
50	      })}
51	    </nav>
52	  );
53	}
54	
55	/**
56	 * Auto-resolving sub-tab bar. Reads the current path, finds the top-level admin
57	 * entry that owns it and renders that entry's <SubTabs />. Dropped once into the
58	 * admin layout so every consolidated page gets its sub-navigation without
59	 * per-page wiring. Renders nothing for paths outside the IA.
60	 */
61	export function AdminSubTabs({
62	  badges,
63	  allowed,
64	}: {
65	  /** Per-route attention counts, keyed by href (same map the sidebar uses). */
66	  badges?: Record<string, number>;
67	  /**
68	   * Hrefs this role may reach, as computed by the layout with canAccessHref().
69	   * Omitted = no filtering. Keeps a SUPPORT/BILLING user from seeing tabs that
70	   * would only bounce them back to /admin.
71	   */
72	  allowed?: string[];
73	}) {
74	  const pathname = usePathname();
75	  const entry = entryForPath(pathname);
76	  if (!entry) return null;
77	  const items = allowed ? entry.tabs.filter((t) => allowed.includes(t.href)) : entry.tabs;
78	  return <SubTabs items={items} badges={badges} />;
79	}
