1	import { db } from "@/lib/db";
2	import { requireArea } from "@/lib/rbac";
3	import { PageHeader } from "@/components/ui/primitives";
4	import { MasterInbox, type ConvoSummary, type ThreadMessage, type Filter } from "@/components/admin/coldemail/Inbox";
5	import type { Prisma } from "@prisma/client";
6	
7	export const dynamic = "force-dynamic";
8	
9	const STATUS_VALUES = [
10	  "OPEN",
11	  "REPLIED",
12	  "INTERESTED",
13	  "NOT_INTERESTED",
14	  "AUTO_REPLY",
15	  "OUT_OF_OFFICE",
16	  "UNSUBSCRIBE",
17	  "CLOSED",
18	] as const;
19	type StatusValue = (typeof STATUS_VALUES)[number];
20	
21	function snippet(text: string): string {
22	  return text.replace(/\s+/g, " ").trim().slice(0, 120);
23	}
24	
25	export default async function ColdEmailInboxPage({
26	  searchParams,
27	}: {
28	  searchParams: Promise<{ c?: string; status?: string; unread?: string; inbox?: string; campaign?: string }>;
29	}) {
30	  await requireArea("platform");
31	  const sp = await searchParams;
32	
33	  const statusParam = STATUS_VALUES.includes(sp.status as StatusValue) ? (sp.status as StatusValue) : "";
34	  const unreadOnly = sp.unread === "1";
35	  const inboxId = sp.inbox ?? "";
36	  const campaignId = sp.campaign ?? "";
37	
38	  const where: Prisma.ConversationWhereInput = {};
39	  if (statusParam) where.status = statusParam;
40	  if (unreadOnly) where.unread = true;
41	  if (inboxId) where.inboxId = inboxId;
42	  if (campaignId) where.campaignId = campaignId;
43	
44	  let convosRaw: Awaited<ReturnType<typeof loadConvos>> = [];
45	  let statusCounts: { status: string; _count: { _all: number } }[] = [];
46	  let unreadCount = 0;
47	  let totalCount = 0;
48	  let inboxes: { id: string; email: string }[] = [];
49	  let campaigns: { id: string; name: string }[] = [];
50	  let tablesReady = true;
51	
52	  try {
53	    [convosRaw, statusCounts, unreadCount, totalCount, inboxes, campaigns] = await Promise.all([
54	      loadConvos(where),
55	      db.conversation.groupBy({ by: ["status"], _count: { _all: true } }),
56	      db.conversation.count({ where: { unread: true } }),
57	      db.conversation.count(),
58	      db.inbox.findMany({ orderBy: { email: "asc" }, select: { id: true, email: true } }),
59	      db.coldCampaign.findMany({ orderBy: { createdAt: "desc" }, select: { id: true, name: true } }),
60	    ]);
61	  } catch {
62	    tablesReady = false;
63	  }
64	
65	  const convos: ConvoSummary[] = convosRaw.map((c) => ({
66	    id: c.id,
67	    subject: c.subject,
68	    status: c.status,
69	    unread: c.unread,
70	    lastMessageAt: c.lastMessageAt.toISOString(),
71	    contactEmail: c.contact.email,
72	    contactName: c.contact.fullName,
73	    contactStage: c.contact.stage,
74	    inboxEmail: c.inbox.email,
75	    campaignName: c.campaign?.name ?? null,
76	    snippet: snippet(c.messages[0]?.bodyText ?? ""),
77	  }));
78	
79	  const selectedId = sp.c && convos.some((c) => c.id === sp.c) ? sp.c : convos[0]?.id ?? null;
80	  const selected = convos.find((c) => c.id === selectedId) ?? null;
81	
82	  let messages: ThreadMessage[] = [];
83	  if (selectedId) {
84	    const msgs = await db.message
85	      .findMany({
86	        where: { conversationId: selectedId },
87	        orderBy: { createdAt: "asc" },
88	        select: { id: true, direction: true, fromAddr: true, toAddr: true, subject: true, bodyText: true, sentAt: true, receivedAt: true, createdAt: true },
89	      })
90	      .catch(() => []);
91	    messages = msgs.map((m) => ({
92	      id: m.id,
93	      direction: m.direction,
94	      fromAddr: m.fromAddr,
95	      toAddr: m.toAddr,
96	      subject: m.subject,
97	      bodyText: m.bodyText,
98	      at: (m.sentAt ?? m.receivedAt ?? m.createdAt).toISOString(),
99	    }));
100	  }
101	
102	  const countFor = (s: string) => statusCounts.find((x) => x.status === s)?._count._all ?? 0;
103	  const statusFilters: Filter[] = [
104	    { key: "all", label: "All", count: totalCount, active: !statusParam && !unreadOnly, query: { status: "", unread: "" } },
105	    { key: "unread", label: "Unread", count: unreadCount, active: unreadOnly, query: { unread: "1", status: "" } },
106	    { key: "OPEN", label: "Open", count: countFor("OPEN"), active: statusParam === "OPEN", query: { status: "OPEN", unread: "" } },
107	    { key: "REPLIED", label: "Replied", count: countFor("REPLIED"), active: statusParam === "REPLIED", query: { status: "REPLIED", unread: "" } },
108	    { key: "INTERESTED", label: "Interested", count: countFor("INTERESTED"), active: statusParam === "INTERESTED", query: { status: "INTERESTED", unread: "" } },
109	    { key: "NOT_INTERESTED", label: "Not interested", count: countFor("NOT_INTERESTED"), active: statusParam === "NOT_INTERESTED", query: { status: "NOT_INTERESTED", unread: "" } },
110	    { key: "UNSUBSCRIBE", label: "Unsubscribe", count: countFor("UNSUBSCRIBE"), active: statusParam === "UNSUBSCRIBE", query: { status: "UNSUBSCRIBE", unread: "" } },
111	  ];
112	
113	  return (
114	    <div className="space-y-6">
115	      <PageHeader
116	        title="Inbox"
117	        sub="Unified reply inbox across every mailbox. Replies stop follow-ups, are classified automatically, and send back from the inbox that received them."
118	      />
119	      {!tablesReady ? (
120	        <div className="card text-sm text-slate-400">
121	          The inbox tables are not migrated on this environment yet. Run a Prisma migration to enable reply capture.
122	        </div>
123	      ) : totalCount === 0 ? (
124	        <div className="card space-y-2">
125	          <p className="text-sm text-slate-300">No conversations yet.</p>
126	          <p className="text-sm text-slate-400">
127	            Configure IMAP credentials on an inbox (Domains &amp; inboxes) and the poller will capture replies here within a
128	            couple of minutes — or use <span className="text-slate-300">Check for replies</span> once one conversation exists.
129	            Reply capture works on a single real mailbox without enabling bulk sending.
130	          </p>
131	        </div>
132	      ) : (
133	        <MasterInbox
134	          convos={convos}
135	          selectedId={selectedId}
136	          selected={selected}
137	          messages={messages}
138	          statusFilters={statusFilters}
139	          inboxes={inboxes}
140	          campaigns={campaigns}
141	          activeInboxId={inboxId}
142	          activeCampaignId={campaignId}
143	        />
144	      )}
145	    </div>
146	  );
147	}
148	
149	function loadConvos(where: Prisma.ConversationWhereInput) {
150	  return db.conversation.findMany({
151	    where,
152	    orderBy: { lastMessageAt: "desc" },
153	    take: 100,
154	    include: {
155	      contact: { select: { email: true, fullName: true, stage: true } },
156	      inbox: { select: { email: true } },
157	      campaign: { select: { name: true } },
158	      messages: { orderBy: { createdAt: "desc" }, take: 1, select: { bodyText: true } },
159	    },
160	  });
161	}
