18	function domainReadiness(d: {
19	  spfVerified: boolean;
20	  dkimVerified: boolean;
21	  dmarcVerified: boolean;
22	  dmarcPolicy: string;
23	  trackingDomain: string;
24	  trackingDomainVerified: boolean;
25	  oneClickUnsub: boolean;
26	}): { label: string; ok: boolean; hint: string }[] {
27	  return [
28	    { label: "SPF + DKIM aligned", ok: d.spfVerified && d.dkimVerified, hint: "Both configured and passing, aligned to the From domain." },
29	    { label: "DMARC published (min p=none)", ok: d.dmarcVerified && d.dmarcPolicy !== "NONE" ? true : d.dmarcVerified, hint: "DMARC record with a RUA reporting tag." },
30	    { label: "One-click unsubscribe (RFC 8058)", ok: d.oneClickUnsub, hint: "List-Unsubscribe + List-Unsubscribe-Post, honoured ≤2 days." },
31	    { label: "Custom tracking domain", ok: !!d.trackingDomain && d.trackingDomainVerified, hint: "Shared tracking domains are blocklisted and tank placement." },
32	  ];
33	}
